<?php require_once __DIR__.'/../includes/functions.php';need_login();if($_SERVER['REQUEST_METHOD']!=='POST')go(role_home());check_csrf();$id=(int)($_POST['id_notifikasi']??0);if($id>0){db()->prepare('UPDATE notifications SET is_read=1 WHERE id_notifikasi=? AND id_pengguna=?')->execute([$id,me()['id_user']]);}else{db()->prepare('UPDATE notifications SET is_read=1 WHERE id_pengguna=?')->execute([me()['id_user']]);}go(role_home());